<?php require __DIR__.'/app/bootstrap.php';Auth::requireLogin();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM transcripts WHERE id=? AND user_id=?');$s->execute([$id,Auth::id()]);$t=$s->fetch();if(!$t){http_response_code(404);exit('Transcript not found');}$s=db()->prepare('SELECT * FROM transcript_segments WHERE transcript_id=? ORDER BY sequence_no');$s->execute([$id]);$segments=$s->fetchAll();$pageTitle='Transcript';require __DIR__.'/app/views/header.php';?><main class="app-shell"><div class="container"><a href="<?=e(url('history.php'))?>">← My transcripts</a><div class="d-flex flex-wrap justify-content-between mt-3 mb-4"><div><span class="status-pill status-<?=e($t['status'])?>"><?=e($t['status'])?></span><h1 class="h2 fw-bold mt-2"><?=e($t['title']?:$t['platform'].' transcript')?></h1><small class="text-secondary"><?=e($t['source_url']?:$t['original_filename'])?></small></div><?php if($t['status']==='completed'):?><div class="d-flex gap-2"><a class="btn btn-outline-primary btn-sm" href="<?=e(url('api/transcripts/export.php?id='.$id.'&format=txt'))?>">TXT</a><a class="btn btn-outline-primary btn-sm" href="<?=e(url('api/transcripts/export.php?id='.$id.'&format=srt'))?>">SRT</a><a class="btn btn-outline-primary btn-sm" href="<?=e(url('api/transcripts/export.php?id='.$id.'&format=vtt'))?>">VTT</a><a class="btn btn-outline-primary btn-sm" href="<?=e(url('api/transcripts/export.php?id='.$id.'&format=json'))?>">JSON</a></div><?php endif?></div><?php if($t['status']==='failed'):?><div class="alert alert-danger"><?=e($t['error_message'])?></div><?php elseif($t['status']!=='completed'):?><div class="panel-card text-center py-5"><div class="spinner-border text-primary"></div><h2 class="h5 mt-3">Transcript <?=e($t['status'])?></h2><p class="text-secondary">This page checks the job status automatically.</p><a class="btn btn-outline-primary" href="">Refresh now</a><script>setInterval(async()=>{try{const r=await fetch('<?=e(url('api/transcripts/status.php?id='.$id))?>');const j=await r.json();if(j.status==='completed'||j.status==='failed')location.reload()}catch(e){}},5000)</script></div><?php else:?><div class="row g-4"><div class="col-lg-8"><section class="panel-card"><div class="d-flex justify-content-between"><h2 class="h5 fw-bold">Transcript text</h2><button class="btn btn-sm btn-outline-secondary" data-copy="#transcriptText">Copy</button></div><div id="transcriptText" class="transcript-body mt-3"><?=e($t['transcript_text'])?></div></section></div><div class="col-lg-4"><section class="panel-card"><h2 class="h5 fw-bold">AI content tools</h2><form method="post" action="<?=e(url('api/ai/generate.php'))?>"><?=csrf_field()?><input type="hidden" name="transcript_id" value="<?=$id?>"><label class="form-label">Generate</label><select class="form-select mb-3" name="task"><?php foreach(['summary'=>'Summary','chapters'=>'Chapters','translate'=>'Translation','linkedin'=>'LinkedIn post','blog'=>'Blog article','newsletter'=>'Newsletter','twitter'=>'X thread','instagram'=>'Instagram caption','youtube'=>'YouTube description','reddit'=>'Reddit post','tiktok'=>'Short video script'] as $k=>$v):?><option value="<?=e($k)?>"><?=e($v)?></option><?php endforeach?></select><input class="form-control mb-3" name="language" value="English" aria-label="Output language"><button class="btn btn-primary w-100">Generate</button></form></section></div></div><?php if($segments):?><section class="panel-card mt-4"><h2 class="h5 fw-bold">Timestamped segments</h2><?php foreach($segments as $seg):?><div class="segment"><time><?=e(duration((int)$seg['start_seconds']))?></time><div><?=e($seg['content'])?></div></div><?php endforeach?></section><?php endif?><?php endif?></div></main><?php require __DIR__.'/app/views/footer.php';?>
